function explainSelectedProgram(problem, code, lang=state.language){
 const lines=code.split('\n');let out=`Goal (${lang}): ${problem.description}\n\nLine-by-line explanation:\n`;
 lines.forEach((line,i)=>{const t=line.trim();if(!t){out+=`${i+1}. (blank line) — separates related code for readability.\n`;return;}let why='This statement contributes to the program logic; trace its values as the program runs.';
 if(/^\/\/|^#|^--|^\/\*/.test(t))why='Comment: gives the programmer guidance and is not executed.';
 else if(/^(import |using |#include|package |use |require\(|<\?php)/.test(t))why='Makes a library or language feature available, or declares the program/module context.';
 else if(/System\.out\.println|console\.log|printf\(|std::cout|Console\.WriteLine|fmt\.Print|println!|puts |echo |SELECT /.test(t))why='Produces the result/output for this example.';
 else if(/input\(|readLine|ReadLine|scanf|std::cin|fmt\.Scan|read_line|gets\(|fgets|stdin|\.nextInt|next\(\)/.test(t))why='Reads input from the user or standard input.';
 else if(/\bif\b|\? .*:|CASE WHEN/.test(t))why='Checks a condition and chooses the appropriate branch or result.';
 else if(/\bfor\b|\.each|while\b|range\(/.test(t))why='Repeats a block for each iteration until its condition or sequence ends.';
 else if(/\breturn\b/.test(t))why='Returns a value to the caller or ends the function.';
 else if(/\b(class|public static void main|static void Main|func main|fn main|def |function )/.test(t))why='Declares a class, function, or program entry point.';
 else if(/\*=|\+=|\+\+|result\s*=|r\s*=/.test(t))why='Updates a variable using the current value and the operation shown.';
 else if(/\b(int|long|double|String|var|let|const|mut|i32|u64)\b/.test(t)||t.includes('='))why='Declares or assigns a variable so its value can be used by later statements.';
 out+=`${i+1}. ${line}\n   Explanation: ${why}\n`;});
 if(/TODO|Implement the solution|Write your SQL solution/.test(code))out+='\nThis is a language-correct starter scaffold, not a completed solution for this specific problem. Use the hint above to implement the missing logic.';
 else out+=`\nHow to study it: trace the input through each statement, write down changing variable values, then test a normal case and an edge case. This explanation is generated from the code structure; verify language-specific details when experimenting.`;
 return out;
}
function explainProgram(problem){const code=practiceProgram(problem,state.language);return explainSelectedProgram(problem,code,state.language)}
function openQuestion(id){currentProblem=QUESTIONS.find(p=>p.id===Number(id));if(!currentProblem)return;const p=currentProblem;$("#modalTopic").textContent=p.topic.toUpperCase();$("#modalTitle").textContent=p.id+". "+p.title;$("#modalBadges").innerHTML=`<span class="badge ${p.difficulty.toLowerCase()}">${p.difficulty}</span> <span class="badge">Question ${p.id}/${QUESTIONS.length}</span>`;$("#modalDesc").textContent=p.description;$("#modalExample").textContent=p.examples;$("#modalHint").textContent=p.hint;$("#approach").innerHTML="<b>Solution approach</b><p>"+esc(p.solutionIdea)+"</p>";$("#approach").classList.add("hidden");$("#toggleApproach").textContent="Show solution approach";$("#questionProgram").textContent=practiceProgram(p,state.language);const programHeading=document.querySelector('#problemModal .example-box b');if(programHeading)programHeading.textContent=`Sample ${state.language} program`;$("#programExplanation").textContent=explainProgram(p);$("#copyProgram").disabled=false;$("#markSolved").disabled=state.solved.includes(p.id);$("#markSolved").textContent=state.solved.includes(p.id)?"✓ Already solved":"✓ Mark as solved";$("#problemModal").classList.add("open")}

function renderDsa(){const q=($("#dsaSearch")?.value||"").toLowerCase().trim(),level=$("#dsaLevel")?.value||"all";const filtered=DSA.map((m,mi)=>({...m,mi,topics:m.topics.filter(t=>(t[0]+" "+t[1]+" "+m.title).toLowerCase().includes(q))})).filter(m=>m.topics.length&&(level==="all"||m.level===level));$("#dsaModules").innerHTML=filtered.length?filtered.map(m=>`<section class="module"><div class="module-head"><span class="module-num">${String(m.mi+1).padStart(2,"0")}</span><div><h3>${esc(m.title)}</h3><p>${esc(m.level)} · ${esc(m.desc||"Study concepts and practise with examples.")}</p></div><span class="module-count">${m.topics.filter(t=>state.dsaDone.includes(t[0])).length}/${m.topics.length} done</span></div>${m.topics.map(t=>{const ix=allDsaTopics().indexOf(t[0]);return `<div class="topic-row ${state.dsaDone.includes(t[0])?"done":""}"><input type="checkbox" data-dsatopic="${esc(t[0])}" id="dsa${ix}" ${state.dsaDone.includes(t[0])?"checked":""}><label for="dsa${ix}">${esc(t[0])}</label><small>${esc(t[1])}</small></div>`}).join("")}<div style="padding:10px 15px"><button class="link" data-dsaquestions="${esc(m.topics.map(t=>t[0]).join("|"))}">Find related practice questions →</button></div></section>`).join(""):'<div class="panel empty">No DSA topics match your search.</div>'}
function renderRoadmap(){progressStats();$("#roadmapList").innerHTML=ROADMAP.map((m,i)=>`<section class="module"><div class="module-head"><span class="module-num">0${i+1}</span><div><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p></div><span class="module-count">${m.topics.filter(t=>state.completed.includes(t[0])).length}/${m.topics.length}</span></div>${m.topics.map((t,j)=>`<div class="topic-row ${state.completed.includes(t[0])?"done":""}"><input type="checkbox" id="road${i}_${j}" data-roadtopic="${esc(t[0])}" ${state.completed.includes(t[0])?"checked":""}><label for="road${i}_${j}">${esc(t[0])}</label><small>${esc(t[1])}</small></div>`).join("")}</section>`).join("")}
function renderMaterials(){const lang=$("#materialLanguage").value||state.language,data=LANGS[lang],topics=(LANGUAGE_SYLLABUS&&LANGUAGE_SYLLABUS[lang])||[];if(!data)return;const search=( $("#conceptSearch")?.value||"").toLowerCase().trim();const filtered=topics.filter(t=>(t.title+" "+t.explanation).toLowerCase().includes(search));const codeFor=t=>t.example||data.hello;$("#materialContent").innerHTML=`<div class="panel"><div style="display:flex;align-items:center;gap:13px"><div class="symbol" style="width:48px;height:48px;font-size:22px"><i class="fa-solid fa-book-open"></i></div><div><h2 style="font-size:18px;margin:0 0 6px">${esc(lang)} complete learning syllabus</h2><p class="muted" style="font-size:11px;margin:0">${esc(data.description)}</p></div></div><div class="hr"></div><span class="badge">Beginner → Advanced</span> <span class="badge">${topics.length} clickable concepts</span><p class="subtle" style="margin-top:12px">Click any concept heading to open its explanation and example. Examples are written in ${esc(lang)} where available.</p></div><div class="toolbar" style="margin:14px 0"><input class="input" id="conceptSearch" placeholder="Search concepts, e.g. loops, OOP, files..." value="${esc(search)}"><span class="pill-tag">${filtered.length} topics</span></div><div class="material-layout"><section class="material-card" style="grid-column:1/-1"><h3><i class="fa-solid fa-graduation-cap accent"></i> All concepts</h3><div class="concept-accordion">${filtered.map((t,i)=>`<details class="concept-item" ${search&&i<3?'open':''}><summary><span>${String(i+1).padStart(2,'0')} · ${esc(t.title)}</span><i class="fa-solid fa-chevron-down"></i></summary><div class="concept-body"><p>${esc(t.explanation)}</p><h4>Example in ${esc(lang)}</h4><pre><code>${esc(codeFor(t))}</code></pre><p class="subtle">Study tip: change one line, predict the result, then run or trace the code in your local development environment.</p></div></details>`).join('')||'<p class="empty">No concepts match your search.</p>'}</div></section><section class="material-card"><h3><i class="fa-solid fa-terminal accent"></i> Starter program</h3><pre><code>${esc(data.hello)}</code></pre><p>Copy the starter program into your local IDE and modify it.</p><hr class="hr"><h3>Suggested learning order</h3><ol>${topics.slice(0,10).map(c=>`<li>${esc(c.title)}</li>`).join('')}</ol></section><section class="material-card"><h3><i class="fa-solid fa-book accent"></i> Key terms</h3><div class="dictionary-list">${data.dictionary.map(d=>`<div class="dict-item"><b>${esc(d[0])}</b><span>${esc(d[1])}</span></div>`).join('')}</div><button class="link" data-goto="dictionary" style="margin-top:13px">Open full dictionary →</button></section><section class="material-card"><h3><i class="fa-solid fa-link accent"></i> Official learning resource</h3><p>Use official documentation to deepen your understanding and check language-specific behavior.</p><a class="resource-link" href="${esc(data.resources.split(': ')[1]||data.resources)}" target="_blank" rel="noopener noreferrer">${esc(data.resources)}</a></section></div>`;$("#conceptSearch").addEventListener('input',()=>{const val=$("#conceptSearch").value;renderMaterials();const input=$("#conceptSearch");input.focus();input.setSelectionRange(val.length,val.length)})}
function renderDictionary(){const lang=$("#dictLanguage").value||state.language,data=LANGS[lang],q=($("#dictSearch").value||"").toLowerCase().trim();const all=[...data.dictionary.map(([term,def])=>({term,def,lang})),...commonDictionary.map(([term,def])=>({term,def,lang:"General"}))];const filtered=all.filter(x=>(x.term+" "+x.def).toLowerCase().includes(q));$("#dictCount").textContent=filtered.length+" TERMS";$("#dictionaryList").innerHTML=filtered.length?filtered.map(x=>`<div class="dict-item"><b>${esc(x.term)}${x.lang==="General"?' <span class="badge">General</span>':""}</b><span>${esc(x.def)}</span></div>`).join(""):'<div class="empty">No matching terms found.</div>'}
const commonDictionary=[
["Algorithm","A finite set of steps to solve a problem."],["API","A defined interface that lets software components communicate."],["Array","An indexed collection of values, commonly stored contiguously."],["Big O","Notation describing how resource requirements grow with input size."],["Boolean","A logical value: true or false."],["Bug","A defect that causes software to behave incorrectly."],["Class","A blueprint defining state and behavior for objects."],["Compiler","A tool that translates source code into another representation."],["Data structure","A way to organize data for efficient access and modification."],["Debugging","Finding, understanding, and fixing defects."],["Dependency","A library or component that software relies on."],["Encapsulation","Bundling data and behavior while controlling access."],["Exception","An event or object representing an error condition."],["Framework","Reusable structure and conventions for building software."],["Function","A reusable block of code that can take inputs and return a result."],["Git","A distributed version-control system."],["Hash map","A key-value data structure commonly offering average O(1) lookup."],["IDE","Integrated development environment for writing, running, and debugging code."],["Immutable","Not changeable after creation."],["Inheritance","A way for a type to derive behavior from another type."],["Interpreter","A program that executes code or an intermediate representation."],["Iteration","Repeating a set of operations, often with a loop."],["Library","Reusable code that an application can call."],["Loop","A control-flow construct that repeats statements."],["Memory leak","Memory that is no longer useful but remains allocated or referenced."],["Method","A function associated with a class or object."],["Object","An instance with state and behavior."],["Parameter","A named input declared by a function or method."],["Polymorphism","Using a common interface for multiple implementations."],["Recursion","A technique where a function calls itself to solve smaller cases."],["Runtime","The period or environment in which a program executes."],["Scope","The region where a name is accessible."],["Stack","A last-in, first-out data structure."],["Syntax","The rules governing valid program structure."],["Test case","A defined input and expected outcome used to check behavior."],["Variable","A named binding used to refer to a value."],["Version control","Tracking changes to files over time."],["Queue","A first-in, first-out data structure."],["Database","An organized collection of data managed for querying and updates."],["JSON","A text format for representing structured data."]
];
function renderInterview(){const q=($("#interviewSearch")?.value||"").toLowerCase().trim(),topic=$("#interviewTopic")?.value||"all";const list=INTERVIEW.filter(x=>(topic==="all"||x[0]===topic)&&(x.join(" ").toLowerCase().includes(q)));$("#interviewList").innerHTML=list.map((x,i)=>`<article class="question"><span class="badge">${esc(x[0])}</span><h3>${esc(x[1])}</h3><button class="link" data-answer="${i}">Reveal answer ↓</button><div class="answer hidden" id="ans${i}">${esc(x[2])}</div></article>`).join("")||'<div class="panel empty">No questions match your search.</div>'}
